-			return nil
-		}
+	err := walkProductionGo(root, func(rel, path string) error {
 		f, err := parser.ParseFile(fset, path, nil, 0)
 		if err != nil {
 			return err
@@ -271,12 +263,12 @@ func TestOnlyTheRouterSetsTheTerminalBackground(t *testing.T) {
 			switch x := n.(type) {
