index 65983926..7545edb3 100644
--- i/internal/jobs/failure.go
+++ w/internal/jobs/failure.go
@@ -26,6 +26,9 @@ type Failure struct {
 	// Detail is the failure reason.
 	Detail string
 	At     time.Time
+	// Seq orders failures: the registry assigns it on pose, strictly increasing
+	// and never reused, even after an eviction or a re-pose of the same key.
+	Seq uint64
 }

 // TargetKey normalizes a target so every view naming the same thing produces
diff --git i/internal/jobs/registry.go w/internal/jobs/registry.go
index fd811d70..0704c37f 100644
--- i/internal/jobs/registry.go
+++ w/internal/jobs/registry.go
@@ -34,6 +34,8 @@ type Registry struct {
 	// failures is the failure memory, oldest first, one entry per FailureKey.
 	// It is independent of runs: pruning a settled run does not touch it.
 	failures []Failure
+	// lastSeq is the Seq of the newest failure ever posed; it never goes back.
+	lastSeq uint64
 }

 // New returns an empty registry.
@@ -488,6 +490,8 @@ func (r *Registry) record(run *Run, item Item) {
 // the newest position; past MaxFailures the oldest entry is evicted.
 func (r *Registry) pose(f Failure) {
 	r.clear(f.FailureKey)
+	r.lastSeq++
+	f.Seq = r.lastSeq
 	r.failures = append(r.failures, f)
 	if excess := len(r.failures) - MaxFailures; excess > 0 {
 		r.failures = slices.Delete(r.failures, 0, excess)
diff --git i/internal/jobs/registry_failure_test.go w/internal/jobs/registry_failure_test.go
index deceb379..63a49efa 100644
--- i/internal/jobs/registry_failure_test.go
+++ w/internal/jobs/registry_failure_test.go
@@ -458,3 +458,42 @@ func TestFailuresReturnsACopy(t *testing.T) {
 		t.Errorf("mutating the result changed the registry: %+v", again)
 	}
 }
+
+func TestFailureSeqIsStrictlyIncreasingAndNeverReused(t *testing.T) {
+	r := New()
+	failItem(r, KindScan, "ctx", "/w/a", "x")
+	failItem(r, KindScan, "ctx", "/w/b", "x")
+	fs := r.Failures()
+	if len(fs) != 2 || fs[0].Seq == 0 || fs[1].Seq <= fs[0].Seq {
+		t.Fatalf("Seq = %+v, want two strictly increasing non-zero values", fs)
+	}
+	oldA := fs[0].Seq
+
+	// Re-posing a key gives it a larger Seq than any before.
+	failItem(r, KindScan, "ctx", "/w/a", "again")
+	fs = r.Failures()
+	if got := LatestFailureSeq(fs); got <= fs[0].Seq || fs[1].Seq <= oldA || fs[1].Seq != got {
+		t.Errorf("re-posed failure Seq = %+v, want it above %d and the newest", fs, oldA)
+	}
+}
+
+func TestFailureSeqSurvivesEviction(t *testing.T) {
+	r := New()
+	for i := 0; i < MaxFailures+5; i++ {
+		failItem(r, KindScan, "ctx", fmt.Sprintf("/w/%d", i), "x")
+	}
+	fs := r.Failures()
+	if len(fs) != MaxFailures {
+		t.Fatalf("kept %d failures, want %d", len(fs), MaxFailures)
+	}
+	seen := map[uint64]bool{}
+	for i, f := range fs {
+		if seen[f.Seq] || (i > 0 && f.Seq <= fs[i-1].Seq) {
+			t.Fatalf("Seq %d at %d reused or out of order", f.Seq, i)
+		}
+		seen[f.Seq] = true
+	}
+	if got := LatestFailureSeq(fs); got != uint64(MaxFailures+5) {
+		t.Errorf("LatestFailureSeq() = %d, want %d (no Seq reused after eviction)", got, MaxFailures+5)
+	}
+}

