293	func TestOnlyTerminalProgressBuildsAProgressBar(t *testing.T) {
294		fset := token.NewFileSet()
295		builds := false
296		err := walkProductionGo("../..", func(rel, path string) error {
297			f, err := parser.ParseFile(fset, path, nil, 0)
298			if err != nil {
299				return err
300			}
301			ast.Inspect(f, func(n ast.Node) bool {
302				var pos token.Pos
303				switch x := n.(type) {
304				case *ast.CallExpr:
305					if sel, ok := x.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "NewProgressBar" {
306						pos = sel.Pos()
307					}
308				case *ast.CompositeLit:
309					if sel, ok := x.Type.(*ast.SelectorExpr); ok && sel.Sel.Name == "ProgressBar" {
310						pos = sel.Pos()
311					}
312				}
313				if pos == token.NoPos {
314					return true
315				}
316				if rel == progressSourceOwner {
317					builds = true
318				} else {
319					t.Errorf("%s builds a tea.ProgressBar; only %s may", fset.Position(pos), progressSourceOwner)
320				}
321				return true
322			})
323			return nil
324		})
325		if err != nil {
326			t.Fatal(err)
327		}
328		if !builds {
329			t.Errorf("%s builds no tea.ProgressBar: the guard would pass vacuously", progressSourceOwner)
330		}
331	}
332

	}
